print_label() {
    printf 'Label: %s\n' "$1"
}
for label in "$@"; do
    print_label "$label"
done

matches() {
    grep -F "$needle" "$1"
}
review() {
    local needle="$1"
    printf 'Topic: %s\n' "$needle"
    matches "$2"
}
needle=$SUMMARY
review "$1" "$3"
review "$2" "$3"
printf 'Review: %s\n' "$needle"
